/**
 * @module core/domain/hub
 *
 * The Hub: one of our distribution hubs (a US metro). Defined with Zod so data
 * coming out of the database is validated before the rest of the code trusts it.
 */
import { z } from "zod";

/** Official US Census Bureau regions — gives "Midwest" a quotable definition. */
export const CENSUS_REGIONS = ["Northeast", "Midwest", "South", "West"] as const;

/** One of the four US Census regions. */
export type CensusRegion = (typeof CENSUS_REGIONS)[number];

/** Schema for a validated hub. */
export const hubSchema = z.object({
  id: z.string().regex(/^[a-z0-9-]+$/),
  name: z.string().min(1),
  state: z.string().length(2),
  region: z.enum(CENSUS_REGIONS),
  latitude: z.number().min(-90).max(90),
  longitude: z.number().min(-180).max(180),
  timezone: z.string().min(1),
  countyFips: z.string().nullable(),
  countyName: z.string().nullable(),
  isActive: z.boolean(),
});

/** A distribution hub. Location is the metro's city-center point. */
export type Hub = z.infer<typeof hubSchema>;

/**
 * @module core/db/client
 *
 * The one place that creates a Supabase client. Server-side only: it uses the
 * secret key, which bypasses RLS, so it must never be imported by browser code.
 */
import { createClient, type SupabaseClient } from "@supabase/supabase-js";
import { getSupabaseEnv } from "../config/env";
import type { Database } from "./database.types";

/** A Supabase client typed against our schema. */
export type Db = SupabaseClient<Database>;

let cachedClient: Db | undefined;

/**
 * Returns a shared, typed Supabase client (created on first use).
 * @returns the database client.
 * @throws BoundaryError (config) when Supabase env variables are missing.
 */
export function getDb(): Db {
  if (!cachedClient) {
    const env = getSupabaseEnv();
    cachedClient = createClient<Database>(env.SUPABASE_URL, env.SUPABASE_SECRET_KEY, {
      auth: { persistSession: false, autoRefreshToken: false },
    });
  }
  return cachedClient;
}

/**
 * @module core/db/hubsRepository
 *
 * Reads hubs from the database and converts rows (snake_case) into validated
 * {@link Hub} objects (camelCase).
 */
import { BoundaryError } from "../errors/boundaryError";
import { hubSchema, type Hub } from "../domain/hub";
import type { Database } from "./database.types";
import { getDb, type Db } from "./client";

type HubRow = Database["public"]["Tables"]["hubs"]["Row"];

/**
 * Converts a database row into a validated Hub.
 * @param row - a row from the `hubs` table.
 * @returns the validated hub.
 * @throws ZodError when the row breaks the hub rules.
 */
export function hubFromRow(row: HubRow): Hub {
  return hubSchema.parse({
    id: row.id,
    name: row.name,
    state: row.state,
    region: row.region,
    latitude: Number(row.latitude),
    longitude: Number(row.longitude),
    timezone: row.timezone,
    countyFips: row.county_fips,
    countyName: row.county_name,
    isActive: row.is_active,
  });
}

/**
 * Lists all active hubs, ordered by id.
 * @param db - database client (injectable for tests).
 * @returns the active hubs.
 * @throws BoundaryError (database) when the query fails or a row is invalid.
 */
export async function listActiveHubs(db: Db = getDb()): Promise<Hub[]> {
  const { data, error } = await db.from("hubs").select("*").eq("is_active", true).order("id");
  if (error) {
    throw new BoundaryError({
      name: "SupabaseQueryError",
      message: `Could not read hubs: ${error.message}`,
      functionName: "listActiveHubs",
      boundary: "database",
      cause: error,
    });
  }
  try {
    return data.map(hubFromRow);
  } catch (cause) {
    throw new BoundaryError({
      name: "HubRowValidationError",
      message: "A row in the hubs table has invalid data",
      functionName: "listActiveHubs",
      boundary: "database",
      cause,
    });
  }
}

import { describe, expect, it } from "vitest";
import { hubFromRow } from "./hubsRepository";

const baseRow = {
  id: "kansas-city",
  name: "Kansas City",
  state: "MO",
  region: "Midwest",
  latitude: 39.0997,
  longitude: -94.5786,
  timezone: "America/Chicago",
  county_fips: null,
  county_name: null,
  is_active: true,
  created_at: "2026-11-25T00:00:00Z",
  updated_at: "2026-11-25T00:00:00Z",
};

describe("hubFromRow", () => {
  it("maps snake_case rows to camelCase hubs", () => {
    expect(hubFromRow(baseRow)).toEqual({
      id: "kansas-city",
      name: "Kansas City",
      state: "MO",
      region: "Midwest",
      latitude: 39.0997,
      longitude: -94.5786,
      timezone: "America/Chicago",
      countyFips: null,
      countyName: null,
      isActive: true,
    });
  });

  it("rejects an unknown region", () => {
    expect(() => hubFromRow({ ...baseRow, region: "Mountain" })).toThrow();
  });
});

/**
 * @module core/db/eventsRepository
 *
 * Writes to the append-only `events` table (ingest runs, scoring, validation
 * failures, retries, guard decisions, errors).
 *
 * Logging an event must never break the main flow, so `recordEvent` does not
 * throw: if the insert fails it prints a formatted error and carries on.
 */
import { formatBoundaryMessage } from "../errors/boundaryError";
import type { Json } from "./database.types";
import { getDb, type Db } from "./client";

/** Which part of the system produced the event (matches the DB check constraint). */
export type EventSource = "ingest" | "scoring" | "agent" | "api" | "guard" | "cron" | "eval";

/** Severity of an event. */
export type EventLevel = "info" | "warn" | "error";

/** A new event to record. */
export interface NewEvent {
  /** Dotted name, e.g. `ingest.started`, `agent.validation_failed`. */
  eventType: string;
  source: EventSource;
  level?: EventLevel;
  /** Groups events from one ingest run or one chat turn. */
  correlationId?: string;
  hubId?: string;
  sessionId?: string;
  message?: string;
  /** Extra structured details (no secrets). */
  payload?: Record<string, Json>;
}

/**
 * Records one event. Never throws — failures are printed to the console.
 * @param event - the event to store.
 * @param db - database client (injectable for tests).
 * @returns true if stored, false if the insert failed.
 */
export async function recordEvent(event: NewEvent, db: Db = getDb()): Promise<boolean> {
  try {
    const { error } = await db.from("events").insert({
      event_type: event.eventType,
      source: event.source,
      level: event.level ?? "info",
      correlation_id: event.correlationId ?? null,
      hub_id: event.hubId ?? null,
      session_id: event.sessionId ?? null,
      message: event.message ?? null,
      payload: event.payload ?? {},
    });
    if (error) throw error;
    return true;
  } catch (error) {
    console.error(
      formatBoundaryMessage({
        name: "EventInsertError",
        message: `Could not record event '${event.eventType}': ${error instanceof Error ? error.message : String(error)}`,
        functionName: "recordEvent",
        boundary: "database",
      }),
    );
    return false;
  }
}

