/**
 * @module core/data/http
 *
 * Shared `fetch` wrapper for external APIs: per-request timeout, retries on
 * rate limits (429), server errors (5xx) and network failures, and errors in
 * the unified boundary format.
 */
import { EXTERNAL_REQUEST_TIMEOUT_MS } from "../config/ingestConfig";
import { BoundaryError, describeUnknownError, type Boundary } from "../errors/boundaryError";

/** A `fetch`-compatible function (injectable for tests). */
export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;

/** Waits for the given milliseconds (injectable for tests). */
export type SleepFn = (ms: number) => Promise<void>;

/** Default sleep using a timer. */
export const sleep: SleepFn = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/** Options for {@link fetchJsonWithRetry}. */
export interface FetchJsonOptions {
  url: string;
  boundary: Boundary;
  functionName: string;
  /** Error name used when every attempt fails, e.g. `OpenMeteoFetchError`. */
  errorName: string;
  fetchImpl?: FetchLike;
  sleepImpl?: SleepFn;
  /** Wait before each retry (its length = number of retries). */
  backoffMs?: number[];
  timeoutMs?: number;
}

/** True for responses worth retrying. */
function isRetryableStatus(status: number): boolean {
  return status === 429 || status >= 500;
}

/**
 * Fetches JSON with timeout and retries.
 * @param options - URL, error labels and injectable fetch/sleep.
 * @returns the parsed JSON body (unvalidated — callers validate with Zod).
 * @throws BoundaryError after the last failed attempt or on a non-retryable HTTP error.
 */
export async function fetchJsonWithRetry(options: FetchJsonOptions): Promise<unknown> {
  const fetchImpl = options.fetchImpl ?? fetch;
  const sleepImpl = options.sleepImpl ?? sleep;
  const backoff = options.backoffMs ?? [2_000, 10_000, 30_000];
  let lastProblem = "unknown error";

  for (let attempt = 0; attempt <= backoff.length; attempt++) {
    try {
      const response = await fetchImpl(options.url, {
        signal: AbortSignal.timeout(options.timeoutMs ?? EXTERNAL_REQUEST_TIMEOUT_MS),
      });
      if (response.ok) return await response.json();

      const body = (await response.text()).slice(0, 300);
      lastProblem = `HTTP ${response.status}: ${body}`;
      if (!isRetryableStatus(response.status)) break;

      const retryAfterSeconds = Number(response.headers.get("retry-after"));
      if (attempt < backoff.length) {
        await sleepImpl(retryAfterSeconds > 0 ? retryAfterSeconds * 1_000 : backoff[attempt]);
      }
    } catch (error) {
      lastProblem = `network error: ${describeUnknownError(error)}`;
      if (attempt < backoff.length) await sleepImpl(backoff[attempt]);
    }
  }

  throw new BoundaryError({
    name: options.errorName,
    message: `Request failed (${lastProblem})`,
    functionName: options.functionName,
    boundary: options.boundary,
  });
}

import { describe, expect, it, vi } from "vitest";
import { fetchJsonWithRetry, type FetchLike } from "./http";

const noSleep = vi.fn(async () => {});

function respond(status: number, body: unknown): Response {
  return new Response(typeof body === "string" ? body : JSON.stringify(body), { status });
}

describe("fetchJsonWithRetry", () => {
  const base = { url: "https://x.test", boundary: "openMeteo" as const, functionName: "f", errorName: "TestError" };

  it("returns JSON on success", async () => {
    const fetchImpl: FetchLike = vi.fn(async () => respond(200, { ok: 1 }));
    await expect(fetchJsonWithRetry({ ...base, fetchImpl, sleepImpl: noSleep })).resolves.toEqual({ ok: 1 });
  });

  it("retries 429 then succeeds", async () => {
    const fetchImpl = vi
      .fn<FetchLike>()
      .mockResolvedValueOnce(respond(429, "slow down"))
      .mockResolvedValueOnce(respond(200, { ok: 2 }));
    await expect(fetchJsonWithRetry({ ...base, fetchImpl, sleepImpl: noSleep, backoffMs: [1] })).resolves.toEqual({
      ok: 2,
    });
    expect(fetchImpl).toHaveBeenCalledTimes(2);
  });

  it("does not retry a 400 and throws in the unified format", async () => {
    const fetchImpl = vi.fn<FetchLike>(async () => respond(400, "bad request"));
    await expect(fetchJsonWithRetry({ ...base, fetchImpl, sleepImpl: noSleep, backoffMs: [1, 1] })).rejects.toThrow(
      "TestError || Request failed (HTTP 400: bad request) || f || 🐸",
    );
    expect(fetchImpl).toHaveBeenCalledTimes(1);
  });

  it("gives up after all retries on network errors", async () => {
    const fetchImpl = vi.fn<FetchLike>(async () => {
      throw new Error("ECONNRESET");
    });
    await expect(fetchJsonWithRetry({ ...base, fetchImpl, sleepImpl: noSleep, backoffMs: [1, 1] })).rejects.toThrow(
      /network error: ECONNRESET/,
    );
    expect(fetchImpl).toHaveBeenCalledTimes(3);
  });
});

/**
 * @module core/data/openMeteo
 *
 * Client for the Open-Meteo Historical Weather API (archive).
 * Docs: https://open-meteo.com/en/docs/historical-weather-api
 *
 * Data is modeled reanalysis (not station measurements) on a ~9–11 km grid.
 * Free tier is non-commercial; attribution (CC BY 4.0) is required.
 */
import { z } from "zod";
import { OPEN_METEO_DAILY_VARIABLES } from "../config/ingestConfig";
import type { DailyWeather } from "../domain/weather";
import { BoundaryError } from "../errors/boundaryError";
import { daysInclusive } from "../utils/dates";
import { fetchJsonWithRetry, type FetchLike, type SleepFn } from "./http";

const ARCHIVE_URL = "https://archive-api.open-meteo.com/v1/archive";

/** What to fetch: one point, one date range. */
export interface ArchiveRequest {
  latitude: number;
  longitude: number;
  /** IANA timezone, so "a day" is the hub's local calendar day. */
  timezone: string;
  startDate: string;
  endDate: string;
}

/** Expected units — if Open-Meteo ever changes them we fail loudly instead of storing wrong numbers. */
const EXPECTED_UNITS = {
  snowfall_sum: "cm",
  temperature_2m_min: "°C",
  precipitation_sum: "mm",
  wind_gusts_10m_max: "km/h",
  apparent_temperature_max: "°C",
} as const;

const nullableNumbers = z.array(z.number().nullable());

/** Shape of the archive response we rely on. */
const archiveResponseSchema = z.object({
  daily_units: z.object(
    Object.fromEntries(OPEN_METEO_DAILY_VARIABLES.map((name) => [name, z.literal(EXPECTED_UNITS[name])])) as {
      [K in keyof typeof EXPECTED_UNITS]: z.ZodLiteral<(typeof EXPECTED_UNITS)[K]>;
    },
  ),
  daily: z.object({
    time: z.array(z.string()),
    snowfall_sum: nullableNumbers,
    temperature_2m_min: nullableNumbers,
    precipitation_sum: nullableNumbers,
    wind_gusts_10m_max: nullableNumbers,
    apparent_temperature_max: nullableNumbers,
  }),
});

/**
 * Builds the archive request URL.
 * @param request - point, timezone and date range.
 * @returns the full URL.
 */
export function buildArchiveUrl(request: ArchiveRequest): string {
  const params = new URLSearchParams({
    latitude: String(request.latitude),
    longitude: String(request.longitude),
    start_date: request.startDate,
    end_date: request.endDate,
    daily: OPEN_METEO_DAILY_VARIABLES.join(","),
    timezone: request.timezone,
  });
  return `${ARCHIVE_URL}?${params.toString()}`;
}

/**
 * Estimates how many "calls" Open-Meteo counts for a request: requests over
 * 10 variables or 14 days count as fractional multiples.
 * @param days - number of days requested.
 * @param variableCount - number of variables requested.
 * @returns the weighted call count (at least 1).
 */
export function estimateCallWeight(days: number, variableCount: number = OPEN_METEO_DAILY_VARIABLES.length): number {
  return Math.max(1, variableCount / 10) * Math.max(1, days / 14);
}

/**
 * Validates an archive response and turns it into one object per day.
 * Trailing days where every value is null (not published yet) are dropped.
 * @param json - the raw response body.
 * @returns the days, oldest first.
 * @throws ZodError when the shape or units are unexpected.
 * @throws Error when the arrays have different lengths.
 */
export function parseArchiveResponse(json: unknown): DailyWeather[] {
  const { daily } = archiveResponseSchema.parse(json);
  const length = daily.time.length;
  for (const name of OPEN_METEO_DAILY_VARIABLES) {
    if (daily[name].length !== length) throw new Error(`Open-Meteo array '${name}' has ${daily[name].length} values, expected ${length}`);
  }

  const days: DailyWeather[] = daily.time.map((date, i) => ({
    date,
    snowfallCm: daily.snowfall_sum[i],
    tempMinC: daily.temperature_2m_min[i],
    precipitationMm: daily.precipitation_sum[i],
    windGustMaxKmh: daily.wind_gusts_10m_max[i],
    apparentTempMaxC: daily.apparent_temperature_max[i],
  }));

  let end = days.length;
  while (end > 0 && isEmptyDay(days[end - 1])) end--;
  return days.slice(0, end);
}

/** True when a day has no values at all. */
function isEmptyDay(day: DailyWeather): boolean {
  return (
    day.snowfallCm === null &&
    day.tempMinC === null &&
    day.precipitationMm === null &&
    day.windGustMaxKmh === null &&
    day.apparentTempMaxC === null
  );
}

/**
 * Fetches daily weather for one point and date range.
 * @param request - point, timezone and date range.
 * @param deps - injectable fetch/sleep for tests.
 * @returns validated days, oldest first.
 * @throws BoundaryError (openMeteo) on HTTP failure or an unexpected response.
 */
export async function fetchDailyWeather(
  request: ArchiveRequest,
  deps: { fetchImpl?: FetchLike; sleepImpl?: SleepFn } = {},
): Promise<DailyWeather[]> {
  if (daysInclusive(request.startDate, request.endDate) === 0) return [];
  const json = await fetchJsonWithRetry({
    url: buildArchiveUrl(request),
    boundary: "openMeteo",
    functionName: "fetchDailyWeather",
    errorName: "OpenMeteoFetchError",
    ...deps,
  });
  try {
    return parseArchiveResponse(json);
  } catch (cause) {
    throw new BoundaryError({
      name: "OpenMeteoResponseError",
      message: `Unexpected archive response for ${request.startDate}..${request.endDate}`,
      functionName: "fetchDailyWeather",
      boundary: "openMeteo",
      cause,
    });
  }
}

import { describe, expect, it, vi } from "vitest";
import { buildArchiveUrl, estimateCallWeight, fetchDailyWeather, parseArchiveResponse } from "./openMeteo";

/** Trimmed copy of a real response (Denver, Nov 2026). */
const realResponse = {
  daily_units: {
    time: "iso8601",
    snowfall_sum: "cm",
    temperature_2m_min: "°C",
    precipitation_sum: "mm",
    wind_gusts_10m_max: "km/h",
    apparent_temperature_max: "°C",
  },
  daily: {
    time: ["2026-11-20", "2026-11-21", "2026-11-22"],
    snowfall_sum: [0, 0.7, null],
    temperature_2m_min: [2.3, -0.6, null],
    precipitation_sum: [0, 1, null],
    wind_gusts_10m_max: [41, 30.6, null],
    apparent_temperature_max: [13.1, 2.7, null],
  },
};

describe("parseArchiveResponse", () => {
  it("maps arrays to days and drops trailing empty days", () => {
    expect(parseArchiveResponse(realResponse)).toEqual([
      { date: "2026-11-20", snowfallCm: 0, tempMinC: 2.3, precipitationMm: 0, windGustMaxKmh: 41, apparentTempMaxC: 13.1 },
      { date: "2026-11-21", snowfallCm: 0.7, tempMinC: -0.6, precipitationMm: 1, windGustMaxKmh: 30.6, apparentTempMaxC: 2.7 },
    ]);
  });

  it("rejects unexpected units (e.g. inches)", () => {
    const inches = { ...realResponse, daily_units: { ...realResponse.daily_units, snowfall_sum: "inch" } };
    expect(() => parseArchiveResponse(inches)).toThrow();
  });

  it("rejects arrays of different lengths", () => {
    const broken = { ...realResponse, daily: { ...realResponse.daily, snowfall_sum: [0] } };
    expect(() => parseArchiveResponse(broken)).toThrow(/expected 3/);
  });
});

describe("estimateCallWeight", () => {
  it("follows Open-Meteo's weighting", () => {
    expect(estimateCallWeight(14, 5)).toBe(1);
    expect(estimateCallWeight(7, 5)).toBe(1);
    expect(estimateCallWeight(28, 5)).toBe(2);
    expect(estimateCallWeight(28, 15)).toBe(3);
  });
});

describe("buildArchiveUrl", () => {
  it("includes the point, range, variables and timezone", () => {
    const url = new URL(
      buildArchiveUrl({ latitude: 39.7, longitude: -105, timezone: "America/Denver", startDate: "2025-01-01", endDate: "2025-12-31" }),
    );
    expect(url.searchParams.get("daily")).toBe(
      "snowfall_sum,temperature_2m_min,precipitation_sum,wind_gusts_10m_max,apparent_temperature_max",
    );
    expect(url.searchParams.get("timezone")).toBe("America/Denver");
    expect(url.searchParams.get("start_date")).toBe("2025-01-01");
  });
});

describe("fetchDailyWeather", () => {
  it("wraps a bad response in an OpenMeteoResponseError", async () => {
    const fetchImpl = vi.fn(async () => new Response(JSON.stringify({ nope: true }), { status: 200 }));
    await expect(
      fetchDailyWeather(
        { latitude: 1, longitude: 1, timezone: "UTC", startDate: "2025-01-01", endDate: "2025-01-02" },
        { fetchImpl },
      ),
    ).rejects.toThrow(/OpenMeteoResponseError \|\| .* \|\| fetchDailyWeather \|\| 🐸/);
  });

  it("skips the request for an empty range", async () => {
    const fetchImpl = vi.fn();
    await expect(
      fetchDailyWeather({ latitude: 1, longitude: 1, timezone: "UTC", startDate: "2025-01-02", endDate: "2025-01-01" }, { fetchImpl }),
    ).resolves.toEqual([]);
    expect(fetchImpl).not.toHaveBeenCalled();
  });
});

/**
 * @module core/data/femaNri
 *
 * Client for the FEMA National Risk Index (NRI) county layer, served by FEMA's
 * public ArcGIS feature service (no key needed). We look up the county that
 * contains a hub's point and keep each hazard's annualized frequency (AFREQ =
 * expected events per year).
 *
 * Data page: https://hazards.fema.gov/nri/data-resources
 */
import { z } from "zod";
import { BoundaryError } from "../errors/boundaryError";
import { fetchJsonWithRetry, type FetchLike, type SleepFn } from "./http";

const COUNTY_LAYER_URL =
  "https://services.arcgis.com/XG15cJAlne2vxtgt/arcgis/rest/services/National_Risk_Index_Counties/FeatureServer/0/query";

/** FEMA hazard codes we use, mapped to our column names. */
export const FEMA_HAZARD_FIELDS = {
  HRCN_AFREQ: "hrcnAfreq", // hurricane
  TRND_AFREQ: "trndAfreq", // tornado
  HAIL_AFREQ: "hailAfreq", // hail
  IFLD_AFREQ: "ifldAfreq", // inland flooding (formerly RFLD)
  CFLD_AFREQ: "cfldAfreq", // coastal flooding
  ISTM_AFREQ: "istmAfreq", // ice storm
  WNTW_AFREQ: "wntwAfreq", // winter weather
  CWAV_AFREQ: "cwavAfreq", // cold wave
  HWAV_AFREQ: "hwavAfreq", // heat wave
  SWND_AFREQ: "swndAfreq", // strong wind
} as const;

type FemaFieldName = keyof typeof FEMA_HAZARD_FIELDS;
type FemaHazardKey = (typeof FEMA_HAZARD_FIELDS)[FemaFieldName];

/** FEMA NRI record for the county containing a hub. `null` frequency = hazard not applicable there. */
export type FemaCountyRecord = {
  countyFips: string;
  countyName: string;
  stateCode: string;
  nriVersion: string;
  /** Every attribute FEMA returned, kept for traceability. */
  rawAttributes: Record<string, unknown>;
} & Record<FemaHazardKey, number | null>;

const ID_FIELDS = ["STCOFIPS", "COUNTY", "STATEABBRV", "NRI_VER"] as const;

const attributesSchema = z
  .object({
    STCOFIPS: z.string().regex(/^\d{5}$/),
    COUNTY: z.string().min(1),
    STATEABBRV: z.string().length(2),
    NRI_VER: z.string().min(1),
    ...Object.fromEntries(
      Object.keys(FEMA_HAZARD_FIELDS).map((field) => [field, z.number().min(0).nullable()]),
    ),
  })
  .loose();

const queryResponseSchema = z.object({
  features: z.array(z.object({ attributes: z.record(z.string(), z.unknown()) })),
});

/**
 * Builds the "which county contains this point?" query URL.
 * @param latitude - point latitude.
 * @param longitude - point longitude.
 * @returns the query URL.
 */
export function buildCountyQueryUrl(latitude: number, longitude: number): string {
  const params = new URLSearchParams({
    geometry: `${longitude},${latitude}`,
    geometryType: "esriGeometryPoint",
    inSR: "4326",
    spatialRel: "esriSpatialRelIntersects",
    outFields: [...ID_FIELDS, ...Object.keys(FEMA_HAZARD_FIELDS)].join(","),
    returnGeometry: "false",
    f: "json",
  });
  return `${COUNTY_LAYER_URL}?${params.toString()}`;
}

/**
 * Validates the ArcGIS response and extracts the county record.
 * @param json - the raw response body.
 * @returns the county record.
 * @throws Error when no county contains the point (e.g. outside the US).
 * @throws ZodError when fields are missing or malformed.
 */
export function parseCountyResponse(json: unknown): FemaCountyRecord {
  const { features } = queryResponseSchema.parse(json);
  if (features.length === 0) throw new Error("No FEMA county contains this point");
  const raw = features[0].attributes;
  const attributes = attributesSchema.parse(raw) as Record<string, unknown>;

  const hazards = Object.fromEntries(
    (Object.entries(FEMA_HAZARD_FIELDS) as [FemaFieldName, FemaHazardKey][]).map(([field, key]) => [
      key,
      attributes[field] as number | null,
    ]),
  ) as Record<FemaHazardKey, number | null>;

  return {
    countyFips: attributes.STCOFIPS as string,
    countyName: attributes.COUNTY as string,
    stateCode: attributes.STATEABBRV as string,
    nriVersion: attributes.NRI_VER as string,
    rawAttributes: raw,
    ...hazards,
  };
}

/**
 * Fetches the FEMA NRI record for the county containing a point.
 * @param latitude - point latitude.
 * @param longitude - point longitude.
 * @param deps - injectable fetch/sleep for tests.
 * @returns the county record.
 * @throws BoundaryError (fema) on HTTP failure, no county, or an unexpected response.
 */
export async function fetchFemaCountyByPoint(
  latitude: number,
  longitude: number,
  deps: { fetchImpl?: FetchLike; sleepImpl?: SleepFn } = {},
): Promise<FemaCountyRecord> {
  const json = await fetchJsonWithRetry({
    url: buildCountyQueryUrl(latitude, longitude),
    boundary: "fema",
    functionName: "fetchFemaCountyByPoint",
    errorName: "FemaFetchError",
    ...deps,
  });
  try {
    return parseCountyResponse(json);
  } catch (cause) {
    throw new BoundaryError({
      name: "FemaResponseError",
      message: `Unexpected FEMA NRI response for point ${latitude},${longitude}: ${cause instanceof Error ? cause.message : "invalid"}`,
      functionName: "fetchFemaCountyByPoint",
      boundary: "fema",
      cause,
    });
  }
}

import { describe, expect, it, vi } from "vitest";
import { buildCountyQueryUrl, fetchFemaCountyByPoint, parseCountyResponse } from "./femaNri";

/** Real response for Denver's city-center point (NRI v1.20). */
const denverResponse = {
  features: [
    {
      attributes: {
        STCOFIPS: "08031",
        COUNTY: "Denver",
        STATEABBRV: "CO",
        NRI_VER: "December 2025",
        HRCN_AFREQ: null,
        TRND_AFREQ: 0.1598618749736841,
        HAIL_AFREQ: 8.290857574357961,
        IFLD_AFREQ: 0.8214285714285714,
        CFLD_AFREQ: null,
        ISTM_AFREQ: 0.015665323352972604,
        WNTW_AFREQ: 13.73781288571919,
        CWAV_AFREQ: 1.2629637216824057,
        HWAV_AFREQ: 0.999741105488073,
        SWND_AFREQ: 1.1887802966092247,
      },
    },
  ],
};

describe("parseCountyResponse", () => {
  it("extracts the county and hazard frequencies (null = not applicable)", () => {
    const record = parseCountyResponse(denverResponse);
    expect(record).toMatchObject({
      countyFips: "08031",
      countyName: "Denver",
      stateCode: "CO",
      nriVersion: "December 2025",
      hrcnAfreq: null,
      cfldAfreq: null,
      wntwAfreq: 13.73781288571919,
      hailAfreq: 8.290857574357961,
    });
    expect(record.rawAttributes.STCOFIPS).toBe("08031");
  });

  it("fails clearly when no county contains the point", () => {
    expect(() => parseCountyResponse({ features: [] })).toThrow(/No FEMA county/);
  });

  it("rejects a missing hazard field", () => {
    const { HAIL_AFREQ: _omitted, ...rest } = denverResponse.features[0].attributes;
    expect(() => parseCountyResponse({ features: [{ attributes: rest }] })).toThrow();
  });
});

describe("buildCountyQueryUrl", () => {
  it("queries by lon,lat point and requests only the fields we use", () => {
    const url = new URL(buildCountyQueryUrl(39.7392, -104.9903));
    expect(url.searchParams.get("geometry")).toBe("-104.9903,39.7392");
    expect(url.searchParams.get("outFields")).toContain("IFLD_AFREQ");
    expect(url.searchParams.get("returnGeometry")).toBe("false");
  });
});

describe("fetchFemaCountyByPoint", () => {
  it("wraps errors in the unified format with the FEMA emoji", async () => {
    const fetchImpl = vi.fn(async () => new Response(JSON.stringify({ features: [] }), { status: 200 }));
    await expect(fetchFemaCountyByPoint(0, 0, { fetchImpl })).rejects.toThrow(
      /FemaResponseError \|\| .*No FEMA county.* \|\| fetchFemaCountyByPoint \|\| 🦡/,
    );
  });
});

