/**
 * @module core/ingest/rateLimiter
 *
 * Keeps Open-Meteo requests under its per-minute, per-hour and per-day limits.
 * Each request has a *weight* (long date ranges count as several calls), so
 * this is a sliding-window limiter over weighted calls.
 *
 * Note: history lives in memory, so it protects one process run. That's enough
 * because the full load is a single run and the nightly run is tiny.
 */
import { sleep as defaultSleep, type SleepFn } from "../data/http";

/** Max weighted calls per window. */
export interface RateLimits {
  perMinute: number;
  perHour: number;
  perDay: number;
}

/** One past request: when it was made and how much it weighed. */
export interface CallRecord {
  at: number;
  weight: number;
}

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/**
 * How long to wait before a request of `weight` can go out without breaking any limit.
 * Pure function: no clock, no side effects.
 * @param history - previous calls (any order).
 * @param now - current time in ms.
 * @param weight - weight of the request we want to make.
 * @param limits - window limits.
 * @returns milliseconds to wait (0 = go now).
 * @throws Error when a single request is heavier than a whole window allows.
 */
export function computeWaitMs(history: CallRecord[], now: number, weight: number, limits: RateLimits): number {
  const windows: [number, number][] = [
    [MINUTE, limits.perMinute],
    [HOUR, limits.perHour],
    [DAY, limits.perDay],
  ];
  let wait = 0;
  for (const [length, limit] of windows) {
    if (weight > limit) throw new Error(`Request weight ${weight} exceeds the ${length / MINUTE}-minute limit ${limit}`);
    // Oldest first: drop calls until the remaining ones leave room for this request.
    const inWindow = history.filter((call) => call.at > now - length).sort((a, b) => a.at - b.at);
    let used = inWindow.reduce((sum, call) => sum + call.weight, 0);
    for (const call of inWindow) {
      if (used + weight <= limit) break;
      used -= call.weight;
      wait = Math.max(wait, call.at + length - now);
    }
  }
  return wait;
}

/** Stateful limiter used by the ingest run. */
export class WeightedRateLimiter {
  private readonly history: CallRecord[] = [];

  /**
   * @param limits - window limits.
   * @param clock - returns the current time (injectable for tests).
   * @param sleepImpl - waits (injectable for tests).
   * @param onWait - called before each wait, e.g. to print progress.
   */
  constructor(
    private readonly limits: RateLimits,
    private readonly clock: () => number = Date.now,
    private readonly sleepImpl: SleepFn = defaultSleep,
    private readonly onWait: (ms: number) => void = () => {},
  ) {}

  /**
   * Waits until a request of `weight` is allowed, then records it.
   * @param weight - weighted call count of the upcoming request.
   * @returns the milliseconds waited.
   */
  async acquire(weight: number): Promise<number> {
    const wait = computeWaitMs(this.history, this.clock(), weight, this.limits);
    if (wait > 0) {
      this.onWait(wait);
      await this.sleepImpl(wait);
    }
    this.history.push({ at: this.clock(), weight });
    return wait;
  }
}

import { describe, expect, it } from "vitest";
import { computeWaitMs, WeightedRateLimiter } from "./rateLimiter";

const limits = { perMinute: 100, perHour: 300, perDay: 1_000 };
const MIN = 60_000;

describe("computeWaitMs", () => {
  it("goes immediately when there is room", () => {
    expect(computeWaitMs([], 0, 50, limits)).toBe(0);
    expect(computeWaitMs([{ at: 0, weight: 40 }], 1_000, 50, limits)).toBe(0);
  });

  it("waits for the minute window when it is full", () => {
    // 90 used at t=0; asking for 20 at t=10s → wait until t=60s (oldest expires).
    expect(computeWaitMs([{ at: 0, weight: 90 }], 10_000, 20, limits)).toBe(50_000);
  });

  it("waits for the hour window even when the minute window is free", () => {
    const history = [
      { at: 0, weight: 100 },
      { at: 2 * MIN, weight: 100 },
      { at: 4 * MIN, weight: 100 },
    ];
    // at 10 min, hour window holds 300; need the first call (t=0) to expire at 60 min.
    expect(computeWaitMs(history, 10 * MIN, 50, limits)).toBe(50 * MIN);
  });

  it("only drops as many old calls as needed", () => {
    const history = [
      { at: 0, weight: 50 },
      { at: 20_000, weight: 50 },
    ];
    // need 30 more within minute: dropping the t=0 call is enough → wait till 60s.
    expect(computeWaitMs(history, 30_000, 30, limits)).toBe(30_000);
  });

  it("refuses a request heavier than a whole window", () => {
    expect(() => computeWaitMs([], 0, 150, limits)).toThrow(/exceeds the 1-minute limit/);
  });
});

describe("WeightedRateLimiter", () => {
  it("sleeps when needed and records each call", async () => {
    let now = 0;
    const sleeps: number[] = [];
    const limiter = new WeightedRateLimiter(
      limits,
      () => now,
      async (ms) => {
        sleeps.push(ms);
        now += ms;
      },
    );
    await limiter.acquire(80);
    await limiter.acquire(80); // minute window would hold 160 > 100 → wait 60s
    expect(sleeps).toEqual([MIN]);
  });
});

/**
 * @module core/ingest/planWeatherRange
 *
 * Decides which days to fetch for one hub, so each run is incremental:
 * - nothing stored yet → everything from the history start to yesterday;
 * - otherwise → any missing days, plus the last N days again (the archive
 *   revises its newest values).
 */
import { addDays, daysInclusive, minDate } from "../utils/dates";

/** Inputs for {@link planWeatherRange}. */
export interface PlanInput {
  /** Newest date already stored for the hub, or null if none. */
  latestStoredDate: string | null;
  /** Today's date (UTC) `YYYY-MM-DD`. We fetch up to yesterday. */
  today: string;
  /** First day of history we keep. */
  historyStart: string;
  /** How many recent days to re-fetch every run. */
  refetchRecentDays: number;
}

/** A date range to fetch, both ends included. */
export interface DateRange {
  startDate: string;
  endDate: string;
}

/**
 * Plans the date range to fetch for one hub.
 * @param input - what's stored, today's date and the policy settings.
 * @returns the range to fetch, or null when there is nothing to do.
 */
export function planWeatherRange(input: PlanInput): DateRange | null {
  const endDate = addDays(input.today, -1);
  if (daysInclusive(input.historyStart, endDate) === 0) return null;

  if (input.latestStoredDate === null) return { startDate: input.historyStart, endDate };

  const firstMissing = addDays(input.latestStoredDate, 1);
  const refetchFrom = addDays(endDate, -(input.refetchRecentDays - 1));
  const startDate = [firstMissing, refetchFrom].reduce(minDate);
  const clampedStart = daysInclusive(input.historyStart, startDate) === 0 ? input.historyStart : startDate;
  return daysInclusive(clampedStart, endDate) === 0 ? null : { startDate: clampedStart, endDate };
}

import { describe, expect, it } from "vitest";
import { planWeatherRange } from "./planWeatherRange";

const policy = { historyStart: "2021-01-01", refetchRecentDays: 7 };

describe("planWeatherRange", () => {
  it("fetches full history for a new hub, up to yesterday", () => {
    expect(planWeatherRange({ ...policy, latestStoredDate: null, today: "2026-11-25" })).toEqual({
      startDate: "2021-01-01",
      endDate: "2026-11-24",
    });
  });

  it("re-fetches the last 7 days when already up to date", () => {
    expect(planWeatherRange({ ...policy, latestStoredDate: "2026-11-24", today: "2026-11-25" })).toEqual({
      startDate: "2026-11-18",
      endDate: "2026-11-24",
    });
  });

  it("covers a gap older than the refetch window", () => {
    expect(planWeatherRange({ ...policy, latestStoredDate: "2026-11-01", today: "2026-11-25" })).toEqual({
      startDate: "2026-11-02",
      endDate: "2026-11-24",
    });
  });

  it("does nothing before history starts", () => {
    expect(planWeatherRange({ ...policy, latestStoredDate: null, today: "2021-01-01" })).toBeNull();
  });

  it("never starts before the history start", () => {
    expect(planWeatherRange({ ...policy, latestStoredDate: "2021-01-02", today: "2021-01-04" })).toEqual({
      startDate: "2021-01-01",
      endDate: "2021-01-03",
    });
  });
});

