  it("winter takes the WORST facet in each half, then averages the halves", () => {
    // observed: snow 20/40 = 50, cold 24/30 = 80 → max 80
    // FEMA: winter weather 25.079 → 100, cold wave 0, ice 0 → max 100
    // winter = (80 + 100) / 2 = 90
    const scores = computeHazardScores(observed({ snowDays: 20, extremeColdDays: 24 }), {
      ...noFema,
      winterWeather: 25.079,
    });
    expect(scores.winter.observedScore).toBeCloseTo(80);
    expect(scores.winter.femaScore).toBeCloseTo(100);
    expect(scores.winter.score).toBeCloseTo(90);
  });

  it("flood FEMA half takes the worse of inland and coastal", () => {
    // inland 1.768/3.536 = 50, coastal 4.917/4.917 = 100 → 100; observed rain 2.5/5 = 50 → (50+100)/2 = 75
    const scores = computeHazardScores(observed({ heavyRainDays: 2.5 }), {
      ...noFema,
      inlandFlood: 1.768,
      coastalFlood: 4.917,
    });
    expect(scores.flood.score).toBeCloseTo(75);
  });

  it("severe storms AVERAGES tornado (per area) and hail", () => {
    // tornado 0.987/yr on 1,000 sq mi = 0.987 per 1,000 → 100; hail 4.0845/8.169 = 50 → avg 75
    const scores = computeHazardScores(observed({}), { ...noFema, tornado: 0.987, hail: 4.0845 });
    expect(scores.severeStorms.score).toBeCloseTo(75);
    expect(scores.severeStorms.observedScore).toBeNull();
  });

  it("scores tornado per area: the same count in a 4× bigger county scores 4× lower", () => {
    const small = computeHazardScores(observed({}), { ...noFema, tornado: 0.4, countyAreaSqMi: 500 });
    const big = computeHazardScores(observed({}), { ...noFema, tornado: 0.4, countyAreaSqMi: 2000 });
    const tornadoScore = (s: typeof small) => s.severeStorms.inputs.find((i) => i.signal === "tornadoPer1000SqMi")!.score!;
    expect(tornadoScore(small)).toBeCloseTo(4 * tornadoScore(big));
  });

  it("hurricane is FEMA-only; 'not applicable' (null) scores 0 with High confidence", () => {
    const scores = computeHazardScores(observed({}), noFema);
    expect(scores.hurricane.score).toBe(0);
    expect(scores.hurricane.confidence).toBe("high");
  });
});

describe("computeHazardScores — realistic regression (Minneapolis, hand-calculated)", () => {
  const scores = computeHazardScores(
    observed({ snowDays: 20.8, extremeColdDays: 26, heavyRainDays: 1.2, gustAdvisoryDays: 2, extremeHeatDays: 0.6 }),
    {
      countyAreaSqMi: 613,
      hurricane: null,
      tornado: 0.458,
      hail: 6.412,
      inlandFlood: 1.536,
      coastalFlood: null,
      iceStorm: 0.485,
      winterWeather: 16.58,
      coldWave: 8.947,
      heatWave: 6.684,
      strongWind: 4.566,
    },
  );

  it("winter ≈ 86.5 = (max(52, 86.7) + max(66.1, 86.3, 31.3)) / 2, High (sources agree)", () => {
    expect(scores.winter.score).toBeCloseTo(86.5, 1);
    expect(scores.winter.confidence).toBe("high");
  });

  it("severe storms ≈ 77.1 = avg(tornado 75.7, hail 78.5)", () => {
    expect(scores.severeStorms.score).toBeCloseTo(77.1, 1);
  });

  it("wind ≈ 46.9 = avg(gusts 20, FEMA 73.8) — Medium because the sources disagree by 53.8", () => {
    expect(scores.wind.score).toBeCloseTo(46.9, 1);
    expect(scores.wind.confidence).toBe("medium");
  });

  it("keeps every input so the agent can explain the number", () => {
    const signals = scores.winter.inputs.map((input) => input.signal);
    expect(signals).toEqual(["snowDays", "extremeColdDays", "winterWeather", "coldWave", "iceStorm"]);
  });
});

import { describe, expect, it } from "vitest";
import { HAZARD_WEIGHTS } from "./config";
import { computeOverall, riskLevelFor } from "./overall";
import type { Hazard } from "./types";

const zeros: Record<Hazard, number> = { hurricane: 0, winter: 0, flood: 0, severeStorms: 0, wind: 0, heat: 0 };

describe("HAZARD_WEIGHTS", () => {
  it("sum to 1", () => {
    expect(Object.values(HAZARD_WEIGHTS).reduce((a, b) => a + b, 0)).toBeCloseTo(1);
  });
});

describe("computeOverall = 60% weighted average + 40% worst hazard", () => {
  it("one severe hazard is not averaged away (hurricane 100, rest 0 → 0.6×25 + 0.4×100 = 55)", () => {
    const result = computeOverall({ ...zeros, hurricane: 100 });
    expect(result.weightedAverage).toBeCloseTo(25);
    expect(result.overallScore).toBeCloseTo(55);
    expect(result.topHazard).toBe("hurricane");
  });

  it("all hazards at 50 → 50", () => {
    const result = computeOverall({ hurricane: 50, winter: 50, flood: 50, severeStorms: 50, wind: 50, heat: 50 });
    expect(result.overallScore).toBeCloseTo(50);
  });

  it("breaks ties by weight order (winter before flood)", () => {
    expect(computeOverall({ ...zeros, winter: 80, flood: 80 }).topHazard).toBe("winter");
  });
});

describe("riskLevelFor (score rounded: Low 0–33, Medium 34–66, High 67–100)", () => {
  it("applies the cut-offs on the rounded score", () => {
    expect(riskLevelFor(0)).toBe("low");
    expect(riskLevelFor(33.4)).toBe("low");
    expect(riskLevelFor(33.5)).toBe("medium");
    expect(riskLevelFor(66.4)).toBe("medium");
    expect(riskLevelFor(66.5)).toBe("high");
    expect(riskLevelFor(100)).toBe("high");
  });
});

import { describe, expect, it } from "vitest";
import { SCORING_VERSION } from "./config";
import type { ObservedSignals } from "./observedSignals";
import { scoreHub } from "./scoreHub";
import type { FemaSignals } from "./types";

const calmObserved: ObservedSignals = {
  window: { start: "2021-11-25", end: "2026-11-24" },
  expectedDays: 1826,
  coverage: { snowfall: 1, tempMin: 1, precipitation: 1, windGust: 1, apparentTempMax: 1 },
  perYear: {
    snowDays: 0,
    heavySnowDays: 0,
    extremeColdDays: 0,
    heavyRainDays: 0,
    gustAdvisoryDays: 0,
    gustWarningDays: 0,
    extremeHeatDays: 0,
  },
};

const hurricaneCoast: FemaSignals = {
  countyAreaSqMi: 1000,
  hurricane: 0.305, // above p95 → 100
  tornado: 0,
  hail: 0,
  inlandFlood: 0,
  coastalFlood: null,
  iceStorm: null,
  winterWeather: 0,
  coldWave: 0,
  heatWave: 0,
  strongWind: 0,
};

describe("scoreHub", () => {
  it("combines hazards into an overall score, level and top hazard", () => {
    const result = scoreHub(calmObserved, hurricaneCoast);
    expect(result.hazards.hurricane.score).toBe(100);
    expect(result.overallScore).toBe(55); // 0.6 × 25 + 0.4 × 100
    expect(result.riskLevel).toBe("medium");
    expect(result.topHazard).toBe("hurricane");
    expect(result.scoringVersion).toBe(SCORING_VERSION);
  });

  it("hub confidence = weakest hazard confidence", () => {
    // Observed says a lot of heat (60/yr → 100), FEMA says none (0) → disagree → heat Medium
    const result = scoreHub(
      { ...calmObserved, perYear: { ...calmObserved.perYear, extremeHeatDays: 60 } },
      hurricaneCoast,
    );
    expect(result.hazards.heat.confidence).toBe("medium");
    expect(result.confidence).toBe("medium");
  });

  it("without any FEMA record every mixed hazard is Low confidence (a source is missing)", () => {
    const result = scoreHub(calmObserved, null);
    expect(result.hazards.winter.confidence).toBe("low");
    expect(result.confidence).toBe("low");
  });

  it("rounds every published score to 1 decimal", () => {
    const result = scoreHub(
      { ...calmObserved, perYear: { ...calmObserved.perYear, snowDays: 13.37 } },
      hurricaneCoast,
    );
    for (const hazard of Object.values(result.hazards)) {
      expect(hazard.score).toBe(Math.round(hazard.score * 10) / 10);
    }
  });
});

