/**
 * @module core/scoring/types
 *
 * Shared vocabulary of the scoring engine. Lists that are mirrored by database
 * check constraints are kept in the same order as the SQL, and
 * `db/schemaDrift.test.ts` fails if they drift.
 */

/** The six hazards we score, in weight order (heaviest first). */
export const HAZARDS = ["hurricane", "winter", "flood", "severeStorms", "wind", "heat"] as const;

/** One of the six scored hazards. */
export type Hazard = (typeof HAZARDS)[number];

/** Overall risk levels. Mirrors `score_snapshots.risk_level`. */
export const RISK_LEVELS = ["low", "medium", "high"] as const;

/** Low / Medium / High risk. */
export type RiskLevel = (typeof RISK_LEVELS)[number];

/** Confidence levels. Mirrors `score_snapshots.confidence`. */
export const CONFIDENCE_LEVELS = ["high", "medium", "low"] as const;

/** How much to trust a score (D51). */
export type Confidence = (typeof CONFIDENCE_LEVELS)[number];

/** Which data source a signal comes from. */
export type SignalSource = "observed" | "fema";

/** One input that went into a hazard score — kept so the agent can explain the number. */
export interface SignalInput {
  /** Machine name, e.g. `snowDays`, `tornadoPer1000SqMi`. */
  signal: string;
  source: SignalSource;
  /** Raw value (per year), or null when not available. */
  value: number | null;
  /** Human unit, e.g. "days/yr", "events/yr". */
  unit: string;
  /** The value that maps to 100. */
  anchor100: number;
  /** 0–100 score of this input, or null when the value is missing. */
  score: number | null;
}

/** The score of one hazard, with everything needed to explain it. */
export interface HazardScore {
  hazard: Hazard;
  /** 0–100, 1 decimal. */
  score: number;
  /** Observed-weather half (null when the hazard has none, or data is missing). */
  observedScore: number | null;
  /** FEMA half (null when missing). */
  femaScore: number | null;
  confidence: Confidence;
  /** Plain-language reason for the confidence level. */
  confidenceReason: string;
  inputs: SignalInput[];
}

/** The full deterministic result for one hub. */
export interface HubScore {
  scoringVersion: string;
  /** 0–100, 1 decimal. */
  overallScore: number;
  /** Weighted average of hazard scores (before mixing in the worst hazard). */
  weightedAverage: number;
  riskLevel: RiskLevel;
  /** The hazard with the highest score. */
  topHazard: Hazard;
  /** Weakest confidence among the hazards. */
  confidence: Confidence;
  hazards: Record<Hazard, HazardScore>;
}

/**
 * Drift tests: some allowed-value lists exist both as a DB check constraint
 * (in the migrations, our schema's source of truth) and as a TypeScript constant.
 * These tests fail the moment the two disagree.
 */
import { readdirSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { CENSUS_REGIONS } from "../domain/hub";
import { EVENT_LEVELS, EVENT_SOURCES } from "./eventsRepository";

const MIGRATIONS_DIR = resolve(__dirname, "../../../supabase/migrations");

/** All migration SQL, in apply order. */
const allMigrationsSql = readdirSync(MIGRATIONS_DIR)
  .filter((file) => file.endsWith(".sql"))
  .sort()
  .map((file) => readFileSync(join(MIGRATIONS_DIR, file), "utf8"))
  .join("\n");

/**
 * Finds `<column> ... check (<column> in ('a', 'b'))` for a column and returns the values.
 * Uses the LAST match, so a later migration that changes the constraint wins.
 * @param column - column name.
 * @returns the allowed values.
 */
function checkConstraintValues(column: string): string[] {
  const pattern = new RegExp(`check\\s*\\(\\s*${column}\\s+in\\s*\\(([^)]*)\\)\\s*\\)`, "gi");
  const matches = [...allMigrationsSql.matchAll(pattern)];
  if (matches.length === 0) throw new Error(`No check constraint found for column '${column}'`);
  return matches.at(-1)![1].split(",").map((value) => value.trim().replace(/^'|'$/g, ""));
}

describe("DB check constraints match TypeScript constants", () => {
  it("hubs.region ↔ CENSUS_REGIONS", () => {
    expect(checkConstraintValues("region")).toEqual([...CENSUS_REGIONS]);
  });

  it("events.source ↔ EVENT_SOURCES", () => {
    expect(checkConstraintValues("source")).toEqual([...EVENT_SOURCES]);
  });

  it("events.level ↔ EVENT_LEVELS", () => {
    expect(checkConstraintValues("level")).toEqual([...EVENT_LEVELS]);
  });
});

