/**
 * @module core/scoring/normalize
 *
 * Turns a raw rate (days or events per year) into a 0–100 score on a fixed,
 * absolute scale: 0 → 0, the anchor → 100, linear in between, capped at 100.
 */

/**
 * Linear 0–100 score with a cap.
 * @param value - raw rate, ≥ 0.
 * @param anchor100 - the rate that scores 100, > 0.
 * @returns score in 0..100 (unrounded).
 * @throws Error on a negative/NaN value or a non-positive anchor — bad inputs must never become a quiet number.
 */
export function linearScore(value: number, anchor100: number): number {
  if (!(anchor100 > 0)) throw new Error(`linearScore: anchor must be > 0, got ${anchor100}`);
  if (!(value >= 0)) throw new Error(`linearScore: value must be a number ≥ 0, got ${value}`);
  return Math.min(100, (value / anchor100) * 100);
}

/**
 * @module core/scoring/observedSignals
 *
 * Turns daily weather rows into per-year "hazard day" rates for the scoring
 * window. Rates use only days that actually have a value:
 *   rate = days meeting the threshold × 365.25 ÷ days with data   (D55)
 * so a few missing days don't drag a hub's rate down; coverage is reported
 * separately and feeds confidence (D51).
 */
import type { DailyWeather } from "../domain/weather";
import { addDays, daysInclusive } from "../utils/dates";
import { DAY_THRESHOLDS, SCORING_WINDOW_DAYS } from "./config";

/** A closed date range `YYYY-MM-DD`..`YYYY-MM-DD`. */
export interface DateWindow {
  start: string;
  end: string;
}

/** Share of expected days that have a value, per weather variable (0..1). */
export interface WeatherCoverage {
  snowfall: number;
  tempMin: number;
  precipitation: number;
  windGust: number;
  apparentTempMax: number;
}

/** Per-year hazard-day rates (null when no day in the window had data). */
export interface PerYearRates {
  snowDays: number | null;
  /** Reported only, not scored (D50). */
  heavySnowDays: number | null;
  extremeColdDays: number | null;
  heavyRainDays: number | null;
  gustAdvisoryDays: number | null;
  /** Reported only, not scored (D20a). */
  gustWarningDays: number | null;
  extremeHeatDays: number | null;
}

/** Observed-weather inputs for one hub. */
export interface ObservedSignals {
  window: DateWindow;
  expectedDays: number;
  coverage: WeatherCoverage;
  perYear: PerYearRates;
}

/**
 * The scoring window: the last {@link SCORING_WINDOW_DAYS} days ending at `latestDate`.
 * @param latestDate - newest stored day for the hub.
 * @returns the window (both ends included).
 */
export function scoringWindow(latestDate: string): DateWindow {
  return { start: addDays(latestDate, -(SCORING_WINDOW_DAYS - 1)), end: latestDate };
}

/**
 * Counts days meeting a condition among days that have a value for one variable.
 * @param days - days in the window.
 * @param pick - reads the variable from a day.
 * @param meets - the threshold test.
 * @returns per-year rate (null when no data) and how many days had data.
 */
function ratePerYear(
  days: DailyWeather[],
  pick: (day: DailyWeather) => number | null,
  meets: (value: number) => boolean,
): { rate: number | null; present: number } {
  let present = 0;
  let hits = 0;
  for (const day of days) {
    const value = pick(day);
    if (value === null) continue;
    present++;
    if (meets(value)) hits++;
  }
  return { rate: present === 0 ? null : (hits * 365.25) / present, present };
}

/**
 * Computes observed hazard-day rates and coverage for a window.
 * @param days - daily rows (rows outside the window are ignored).
 * @param window - the scoring window.
 * @returns per-year rates and per-variable coverage.
 */
export function computeObservedSignals(days: DailyWeather[], window: DateWindow): ObservedSignals {
  const inWindow = days.filter((day) => day.date >= window.start && day.date <= window.end);
  const expectedDays = daysInclusive(window.start, window.end);
  const t = DAY_THRESHOLDS;

  const snow = ratePerYear(inWindow, (d) => d.snowfallCm, (v) => v >= t.snowDayCm);
  const heavySnow = ratePerYear(inWindow, (d) => d.snowfallCm, (v) => v >= t.heavySnowDayCm);
  const cold = ratePerYear(inWindow, (d) => d.tempMinC, (v) => v <= t.extremeColdC);
  const rain = ratePerYear(inWindow, (d) => d.precipitationMm, (v) => v >= t.heavyRainMm);
  const gustAdvisory = ratePerYear(inWindow, (d) => d.windGustMaxKmh, (v) => v >= t.gustAdvisoryKmh);
  const gustWarning = ratePerYear(inWindow, (d) => d.windGustMaxKmh, (v) => v >= t.gustWarningKmh);
  const heat = ratePerYear(inWindow, (d) => d.apparentTempMaxC, (v) => v >= t.extremeHeatApparentC);

  const share = (present: number) => (expectedDays === 0 ? 0 : present / expectedDays);
  return {
    window,
    expectedDays,
    coverage: {
      snowfall: share(snow.present),
      tempMin: share(cold.present),
      precipitation: share(rain.present),
      windGust: share(gustAdvisory.present),
      apparentTempMax: share(heat.present),
    },
    perYear: {
      snowDays: snow.rate,
      heavySnowDays: heavySnow.rate,
      extremeColdDays: cold.rate,
      heavyRainDays: rain.rate,
      gustAdvisoryDays: gustAdvisory.rate,
      gustWarningDays: gustWarning.rate,
      extremeHeatDays: heat.rate,
    },
  };
}

/**
 * @module core/scoring/confidence
 *
 * Rule-based confidence (D51), computed in code — never by the LLM.
 * Trust depends on whether data is complete and whether sources AGREE,
 * not on how many sources there are.
 */
import { CONFIDENCE_RULES } from "./config";
import { CONFIDENCE_LEVELS, type Confidence } from "./types";

/** A confidence level plus a plain-language reason the agent can quote. */
export interface ConfidenceResult {
  confidence: Confidence;
  reason: string;
}

/**
 * Confidence for a hazard scored from observed weather AND FEMA.
 * @param input - the two halves (null = missing) and the observed data coverage (0..1).
 * @returns level and reason.
 */
export function hybridConfidence(input: {
  observedScore: number | null;
  femaScore: number | null;
  coverage: number;
}): ConfidenceResult {
  const { observedScore, femaScore, coverage } = input;
  const percentMissing = Math.round((1 - coverage) * 100);

  if (observedScore === null || femaScore === null) {
    const missing = observedScore === null ? "observed weather" : "FEMA";
    return { confidence: "low", reason: `Only one of two sources is available (${missing} data is missing).` };
  }
  if (coverage < CONFIDENCE_RULES.minimumCoverage) {
    return { confidence: "low", reason: `${percentMissing}% of days in the window have no weather data.` };
  }
  if (coverage < CONFIDENCE_RULES.completeCoverage) {
    return { confidence: "medium", reason: `${percentMissing}% of days in the window have no weather data.` };
  }
  const gap = Math.abs(observedScore - femaScore);
  if (gap > CONFIDENCE_RULES.disagreementPoints) {
    return {
      confidence: "medium",
      reason: `The two sources disagree: observed weather scores ${Math.round(observedScore)}, FEMA's long-term county record scores ${Math.round(femaScore)}.`,
    };
  }
  return { confidence: "high", reason: "Complete data, and observed weather and FEMA's record tell the same story." };
}

/**
 * Confidence for a hazard scored from FEMA only (hurricane, severe storms):
 * FEMA's long historical record is the right source for rare events.
 * @param femaScore - the FEMA score, or null when the record is missing.
 * @returns level and reason.
 */
export function femaOnlyConfidence(femaScore: number | null): ConfidenceResult {
  if (femaScore === null) return { confidence: "low", reason: "No FEMA record is available for this hub's county." };
  return { confidence: "high", reason: "Based on FEMA's long-term county frequency record (rare events need decades of data)." };
}

/**
 * The weakest of several confidence levels.
 * @param levels - at least one level.
 * @returns the lowest one.
 * @throws Error on an empty list.
 */
export function weakestConfidence(levels: Confidence[]): Confidence {
  if (levels.length === 0) throw new Error("weakestConfidence needs at least one level");
  return levels.reduce((weakest, level) =>
    CONFIDENCE_LEVELS.indexOf(level) > CONFIDENCE_LEVELS.indexOf(weakest) ? level : weakest,
  );
}

/**
 * @module core/scoring/hazards
 *
 * Scores each of the six hazards 0–100 from observed weather and FEMA (D18, D49, D53):
 *
 * | Hazard        | Observed half                     | FEMA half                                   |
 * |---------------|-----------------------------------|---------------------------------------------|
 * | hurricane     | —                                 | hurricane                                   |
 * | winter        | max(snow days, extreme cold days) | max(winter weather, cold wave, ice storm)   |
 * | flood         | heavy rain days                   | max(inland flood, coastal flood)            |
 * | severeStorms  | —                                 | avg(tornado per 1,000 sq mi, hail)          |
 * | wind          | gust ≥72 km/h days                | strong wind                                 |
 * | heat          | extreme heat days                 | heat wave                                   |
 *
 * Hazard score = average of the halves that exist.
 */
import { FEMA_ANCHORS_P95 as FEMA, OBSERVED_ANCHORS as OBS } from "./config";
import { femaOnlyConfidence, hybridConfidence, type ConfidenceResult } from "./confidence";
import { linearScore } from "./normalize";
import type { ObservedSignals } from "./observedSignals";
import type { FemaSignals, Hazard, HazardScore, SignalInput } from "./types";

/**
 * Builds one scored input. Missing observed values stay null; FEMA "not applicable" (null) scores 0 (D18).
 * @returns the input with its score.
 */
function input(
  signal: string,
  source: SignalInput["source"],
  value: number | null,
  unit: string,
  anchor100: number,
  nullMeansZero: boolean,
): SignalInput {
  const effective = value === null && nullMeansZero ? 0 : value;
  return { signal, source, value, unit, anchor100, score: effective === null ? null : linearScore(effective, anchor100) };
}

/** Max / average of the non-null scores of some inputs (null if none). */
function combine(inputs: SignalInput[], how: "max" | "avg"): number | null {
  const scores = inputs.map((i) => i.score).filter((s): s is number => s !== null);
  if (scores.length === 0) return null;
  return how === "max" ? Math.max(...scores) : scores.reduce((a, b) => a + b, 0) / scores.length;
}

/** Rounds to 1 decimal (published precision). */
const round1 = (value: number) => Math.round(value * 10) / 10;

/**
 * Assembles a hazard score from its halves.
 * @returns the rounded hazard score with confidence and inputs.
 */
function assemble(
  hazard: Hazard,
  observedInputs: SignalInput[],
  observedHow: "max" | "avg",
  femaInputs: SignalInput[],
  femaHow: "max" | "avg",
  coverage: number,
  hasFemaRecord: boolean,
): HazardScore {
  const observedScore = observedInputs.length > 0 ? combine(observedInputs, observedHow) : null;
  const femaScore = hasFemaRecord ? combine(femaInputs, femaHow) : null;
  const halves = [observedScore, femaScore].filter((s): s is number => s !== null);
  const score = halves.length === 0 ? 0 : halves.reduce((a, b) => a + b, 0) / halves.length;

  const confidence: ConfidenceResult =
    observedInputs.length === 0
      ? femaOnlyConfidence(femaScore)
      : hybridConfidence({ observedScore, femaScore, coverage });

  return {
    hazard,
    score: round1(score),
    observedScore: observedScore === null ? null : round1(observedScore),
    femaScore: femaScore === null ? null : round1(femaScore),
    ...confidence,
    inputs: [...observedInputs, ...(hasFemaRecord ? femaInputs : [])],
  };
}

/**
 * Scores all six hazards for one hub.
 * @param observed - observed-weather signals, or null when no weather data exists.
 * @param fema - FEMA county signals, or null when no FEMA record exists.
 * @returns a score per hazard.
 */
export function computeHazardScores(observed: ObservedSignals | null, fema: FemaSignals | null): Record<Hazard, HazardScore> {
  const o = observed?.perYear;
  const cov = observed?.coverage;
  const hasFema = fema !== null;
  const f = fema ?? ({} as Partial<FemaSignals>);
  const days = "days/yr";
  const events = "events/yr";
  const obs = (signal: keyof typeof OBS, value: number | null | undefined) =>
    input(signal, "observed", value ?? null, days, OBS[signal], false);
  const fem = (signal: keyof typeof FEMA, value: number | null | undefined, unit = events) =>
    input(signal, "fema", value ?? null, unit, FEMA[signal], true);

  const tornadoDensity =
    f.tornado === undefined || f.tornado === null || !f.countyAreaSqMi ? null : (f.tornado / f.countyAreaSqMi) * 1_000;

  return {
    hurricane: assemble("hurricane", [], "max", [fem("hurricane", f.hurricane)], "max", 1, hasFema),
    winter: assemble(
      "winter",
      observed ? [obs("snowDays", o?.snowDays), obs("extremeColdDays", o?.extremeColdDays)] : [obs("snowDays", null), obs("extremeColdDays", null)],
      "max",
      [fem("winterWeather", f.winterWeather), fem("coldWave", f.coldWave, "event-days/yr"), fem("iceStorm", f.iceStorm, "event-days/yr")],
      "max",
      Math.min(cov?.snowfall ?? 0, cov?.tempMin ?? 0),
      hasFema,
    ),
    flood: assemble(
      "flood",
      [obs("heavyRainDays", o?.heavyRainDays)],
      "max",
      [fem("inlandFlood", f.inlandFlood, "event-days/yr"), fem("coastalFlood", f.coastalFlood)],
      "max",
      cov?.precipitation ?? 0,
      hasFema,
    ),
    severeStorms: assemble(
      "severeStorms",
      [],
      "max",
      [fem("tornadoPer1000SqMi", tornadoDensity, "events/yr per 1,000 sq mi"), fem("hail", f.hail)],
      "avg",
      1,
      hasFema,
    ),
    wind: assemble("wind", [obs("gustAdvisoryDays", o?.gustAdvisoryDays)], "max", [fem("strongWind", f.strongWind)], "max", cov?.windGust ?? 0, hasFema),
    heat: assemble(
      "heat",
      [obs("extremeHeatDays", o?.extremeHeatDays)],
      "max",
      [fem("heatWave", f.heatWave, "event-days/yr")],
      "max",
      cov?.apparentTempMax ?? 0,
      hasFema,
    ),
  };
}

/**
 * @module core/scoring/overall
 *
 * Combines the six hazard scores into one overall score (D19):
 *   overall = 60% × weighted average + 40% × worst hazard
 * so one severe hazard (e.g. Miami hurricanes) is never averaged away.
 */
import { HAZARD_WEIGHTS, OVERALL_MIX, RISK_LEVEL_CUTOFFS } from "./config";
import { HAZARDS, type Hazard, type RiskLevel } from "./types";

/** Overall result before rounding/assembly. */
export interface OverallResult {
  overallScore: number;
  weightedAverage: number;
  /** Highest-scoring hazard; ties go to the heavier-weighted hazard. */
  topHazard: Hazard;
}

/**
 * Computes the overall score from hazard scores.
 * @param scores - 0–100 score per hazard.
 * @returns overall score, weighted average and top hazard.
 */
export function computeOverall(scores: Record<Hazard, number>): OverallResult {
  const weightedAverage = HAZARDS.reduce((sum, hazard) => sum + HAZARD_WEIGHTS[hazard] * scores[hazard], 0);
  // HAZARDS is in weight order, so a strict ">" keeps the heavier hazard on ties.
  const topHazard = HAZARDS.reduce((top, hazard) => (scores[hazard] > scores[top] ? hazard : top), HAZARDS[0]);
  const overallScore = OVERALL_MIX.weightedAverage * weightedAverage + OVERALL_MIX.worstHazard * scores[topHazard];
  return { overallScore, weightedAverage, topHazard };
}

/**
 * Risk level for an overall score, using the score rounded to a whole number:
 * Low 0–33, Medium 34–66, High 67–100.
 * @param score - 0–100.
 * @returns the level.
 */
export function riskLevelFor(score: number): RiskLevel {
  const rounded = Math.round(score);
  if (rounded >= RISK_LEVEL_CUTOFFS.highFrom) return "high";
  if (rounded >= RISK_LEVEL_CUTOFFS.mediumFrom) return "medium";
  return "low";
}

/**
 * @module core/scoring/scoreHub
 *
 * The one entry point for scoring a hub: hazard scores → overall → level →
 * confidence. Pure and deterministic: same inputs, same output, always.
 */
import { SCORING_VERSION } from "./config";
import { weakestConfidence } from "./confidence";
import { computeHazardScores } from "./hazards";
import type { ObservedSignals } from "./observedSignals";
import { computeOverall, riskLevelFor } from "./overall";
import { HAZARDS, type FemaSignals, type Hazard, type HubScore } from "./types";

/** Rounds to 1 decimal (published precision). */
const round1 = (value: number) => Math.round(value * 10) / 10;

/**
 * Scores one hub.
 * @param observed - observed-weather signals for the window (null if none).
 * @param fema - FEMA county signals (null if no record).
 * @returns the full, explainable score.
 */
export function scoreHub(observed: ObservedSignals | null, fema: FemaSignals | null): HubScore {
  const hazards = computeHazardScores(observed, fema);
  // The overall is computed from the published (rounded) hazard scores, so the numbers the agent shows add up.
  const scores = Object.fromEntries(HAZARDS.map((h) => [h, hazards[h].score])) as Record<Hazard, number>;
  const overall = computeOverall(scores);
  const overallScore = round1(overall.overallScore);
  return {
    scoringVersion: SCORING_VERSION,
    overallScore,
    weightedAverage: round1(overall.weightedAverage),
    riskLevel: riskLevelFor(overallScore),
    topHazard: overall.topHazard,
    confidence: weakestConfidence(HAZARDS.map((h) => hazards[h].confidence)),
    hazards,
  };
}

